-- ===== migrations/0049-cell-table-stations.sql =====
-- Cell table scales: registered stations with a device token, a stable flag,
-- and a log of settled weights.
-- Koa 2026-11-05: "All parts have arrived for our test scale, now we just need
-- software with it." Design: wiki operations/plans/2026-11-02-cell-software-design.md §3.
--
-- Read by setScaleWeight / getScaleWeight (workers/src/handlers/production/scale.js):
--   * a station registered here with kind = 'table' must send
--     Authorization: Bearer <token>; only the SHA-256 hex of the token is stored.
--     Register one with: node workers/scripts/scale-station-sql.mjs (prints the INSERT).
--   * an unregistered station (line1, the QC bag scale) keeps the old behaviour:
--     no token, 3 s stale.
--   * scale_events gets one row per settled weight that moved 0.2 g or more.
--
-- Run ONCE. The ALTER TABLE is not idempotent in SQLite (a second run fails on
-- the duplicate column; the CREATEs are safe to repeat).
-- Apply by hand: cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0049-cell-table-stations.sql

ALTER TABLE scale_readings ADD COLUMN stable INTEGER;

CREATE TABLE IF NOT EXISTS scale_stations (
  station_id    TEXT PRIMARY KEY,
  label         TEXT,
  kind          TEXT NOT NULL DEFAULT 'table',   -- 'table' needs a token; 'qc' is the bag-station scale
  token_hash    TEXT,                            -- SHA-256 hex of the device token
  stale_after_s INTEGER NOT NULL DEFAULT 45,
  active        INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS scale_events (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  station_id TEXT NOT NULL,
  ts         TEXT NOT NULL DEFAULT (datetime('now')),
  weight_kg  REAL NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_scale_events_station ON scale_events (station_id, id);

-- ===== migrations/0050-cell-hourly.sql =====
-- Manual hour-by-hour cell log, until every table has a live scale.
-- Koa 2026-11-09: ~21 cells working today, add more with a button; rename a cell
-- (person or label) over a stable station id; per cell per hour: tops, notes,
-- quality pass/fail; smalls is one number for the whole room each hour.
-- Design: wiki operations/plans/2026-11-02-cell-software-design.md §3 (cell_hourly).
--
-- Read and written by workers/src/handlers/production/cell-hourly.js
-- (?action=cellHourly / setCellHourly / setRoomSmalls / saveCellRoster).
-- Keys match what the scale rollup will write later (station_id = table1..tableN,
-- the canonical hourly-entry time slots), so scales replace typing with no data
-- migration: a scale row is the same row with source = 'scale'.
-- Nothing here writes to monthly_production (cell pounds stay out of line totals).
--
-- Safe to re-run: every statement is IF NOT EXISTS / OR IGNORE.
-- Apply by hand: cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0050-cell-hourly.sql

CREATE TABLE IF NOT EXISTS cell_roster (
  station_id TEXT PRIMARY KEY,                 -- table1..tableN, never reused
  label      TEXT NOT NULL,                    -- shown over the id: a person or a label
  lane       TEXT NOT NULL DEFAULT 'wholesale' CHECK (lane IN ('wholesale', 'retail')),
  sort       INTEGER NOT NULL,
  active     INTEGER NOT NULL DEFAULT 1,       -- a removed cell is 0, never deleted
  updated_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS cell_hourly (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  production_date TEXT NOT NULL,               -- YYYY-MM-DD, Pacific
  time_slot       TEXT NOT NULL,               -- canonical hourly-entry slot (en dash)
  station_id      TEXT NOT NULL,
  cultivar        TEXT,
  tops_lbs        REAL,
  quality         TEXT CHECK (quality IN ('pass', 'fail')),   -- NULL = not checked
  notes           TEXT,
  source          TEXT NOT NULL DEFAULT 'manual',             -- 'manual' | 'scale'
  updated_at      TEXT DEFAULT (datetime('now')),
  UNIQUE (production_date, time_slot, station_id)
);
CREATE INDEX IF NOT EXISTS idx_cell_hourly_date ON cell_hourly (production_date);

CREATE TABLE IF NOT EXISTS cell_room_hourly (
  production_date TEXT NOT NULL,
  time_slot       TEXT NOT NULL,
  smalls_lbs      REAL,                        -- one shared number for the room
  cultivar        TEXT,                        -- the room's cultivar this hour (cells default to it)
  updated_at      TEXT DEFAULT (datetime('now')),
  PRIMARY KEY (production_date, time_slot)
);

-- Marks the cell screen sends for a scale station, so the Worker can work out
-- hourly tops from settled readings (workers/src/lib/cell-auto.js):
--   tare   = the empty basket's gross when Tare was pressed (the Worker only sees gross)
--   pickup = the finished job was lifted off for bagging
CREATE TABLE IF NOT EXISTS scale_marks (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  station_id TEXT NOT NULL,
  ts         TEXT NOT NULL DEFAULT (datetime('now')),
  kind       TEXT NOT NULL CHECK (kind IN ('tare', 'pickup')),
  kg         REAL
);
CREATE INDEX IF NOT EXISTS idx_scale_marks_station ON scale_marks (station_id, ts);

