-- ===== migrations/0052-cell-job-order.sql =====
-- What each cell job was (Koa 2026-11-09, made-to-order retail trial): the cell
-- screen picks a cultivar and a bag size for the order, and the target follows
-- the bag size. A finished job already posts a 'pickup' mark (migration 0050);
-- that mark now also carries the order's cultivar, bag size and the job's
-- working time (pauses left out), so the hourly log and later pace-per-cultivar
-- reports know what each job was. All NULL on tare marks and older pickups.
--
--   bag: qOz | hOz | oz1 | qLb | hLb | lb1   (fill-weight standards, net)
--
-- Run ONCE: ALTER TABLE ADD COLUMN is not idempotent in SQLite. The Worker
-- still saves the plain mark if this hasn't been applied yet.
-- Apply by hand:
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0052-cell-job-order.sql

ALTER TABLE scale_marks ADD COLUMN cultivar TEXT;
ALTER TABLE scale_marks ADD COLUMN bag TEXT;
ALTER TABLE scale_marks ADD COLUMN cycle_s INTEGER;

-- ===== migrations/0053-scale-down-since.sql =====
-- Cell scale watch (Koa 2026-11-09): a table scale that goes silent mid-shift
-- sends Koa one Telegram message, and one more when it's back. down_since is the
-- last post before the outage, set when the alert goes out and cleared when the
-- scale posts again (workers/src/lib/scale-watch.js, 5-minute cron).
--
-- Run ONCE: ALTER TABLE ADD COLUMN is not idempotent in SQLite. Until it's
-- applied the cron logs an error and sends nothing; nothing else is affected.
-- Apply by hand:
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --command "ALTER TABLE scale_stations ADD COLUMN down_since TEXT"

ALTER TABLE scale_stations ADD COLUMN down_since TEXT;

-- ===== migrations/0054-cell-screen-state.sql =====
-- What each cell's screen is doing right now, so other computers can see it
-- (Koa 2026-11-09: "once everything renders on the cell 1 tablet, id like to see
-- it pop up on other's computers"). The cell tablet posts this on every job
-- change and every 30 s (setCellState); the Cells board reads it with the live
-- scale weight (cellBoard). One row per station, overwritten each time.
--
-- Times are Worker epoch ms, never the tablet's clock: clock_start is when the
-- job's working clock would have read 0 (now - the tablet's elapsed time) while
-- it runs; clock_ms is the frozen value while paused or finished. finished_at is
-- when the job first reached 'finished', kept until it leaves that phase (the
-- bag is lifted for pickup).
--
-- Safe to run twice. Apply by hand:
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0054-cell-screen-state.sql

CREATE TABLE IF NOT EXISTS cell_screen_state (
  station_id     TEXT PRIMARY KEY,
  phase          TEXT NOT NULL CHECK (phase IN ('idle', 'armed', 'running', 'finished')),
  cultivar       TEXT,
  bag            TEXT,
  target_g       REAL,
  clock_start    INTEGER,
  clock_ms       INTEGER,
  paused         INTEGER NOT NULL DEFAULT 0,
  pause_note     TEXT,
  finished_net_g REAL,
  finished_at    INTEGER,
  updated_at     INTEGER NOT NULL
);

-- ===== migrations/0055-scale-node-battery.sql =====
-- Scale node battery and Wi-Fi signal (Koa 2026-11-10: "Are we able to see
-- feather battery % somewhere too?"). The Feather ESP32 V2 reads its own LiPo
-- through the VBAT divider on GPIO 35 and sends it with each post (firmware
-- v6.5+), with its Wi-Fi RSSI. The Worker keeps the latest per station and
-- turns millivolts into a percent (lib/battery.js).
--
--   scale_readings.batt_mv    battery millivolts, latest
--   scale_readings.rssi       Wi-Fi signal, dBm, latest
--   scale_readings.batt_at    when the node last sent them (UTC, SQLite text)
--   scale_stations.batt_low_at  when the low-battery Telegram went out; cleared
--                               once the battery reads charged again
--
-- ALTER TABLE ADD COLUMN can't be repeated: apply ONCE, by hand.
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0055-scale-node-battery.sql
-- Until it is applied the Worker ignores the new fields; nothing breaks.

ALTER TABLE scale_readings ADD COLUMN batt_mv INTEGER;
ALTER TABLE scale_readings ADD COLUMN rssi INTEGER;
ALTER TABLE scale_readings ADD COLUMN batt_at TEXT;
ALTER TABLE scale_stations ADD COLUMN batt_low_at TEXT;

