-- ===== migrations/0058-order-queue.sql =====
-- Order flow, slice 1: Shopify orders in a FIFO queue for bag/tag (design doc
-- §2e, wiki operations/plans/2026-11-02-cell-software-design.md; Koa 2026-11-10:
-- "Approve, start slice 1").
--
-- The Worker polls Shopify (lib/shopify.js, lib/order-sync.js) and keeps one row
-- per open order and per line. NO buyer fields and NO prices are stored or even
-- asked for: order number, cultivar, form, bag size and counts only. The wholesale
-- Production Queue (orders / order_items) is a different thing and is untouched.
--
-- New tables only, IF NOT EXISTS: running this twice is harmless.
-- Apply by hand:
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0058-order-queue.sql

CREATE TABLE IF NOT EXISTS shop_orders (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  shop_gid         TEXT NOT NULL UNIQUE,             -- gid://shopify/Order/123: the dedup key
  name             TEXT NOT NULL,                    -- "#1234", display only
  placed_at        TEXT NOT NULL,                    -- UTC ISO, from Shopify createdAt
  intake_tag       TEXT,                             -- 'm2o' | 'wholesale' | NULL (in by the go-live date)
  rush             INTEGER NOT NULL DEFAULT 0,       -- 1 = expedited shipping (or set by hand, later)
  rush_why         TEXT,                             -- the shipping method title that made it rush
  state            TEXT NOT NULL DEFAULT 'queued'
                   CHECK (state IN ('queued', 'assigned', 'trimming', 'ready', 'checked', 'fulfilled', 'cancelled', 'hold')),
  shop_status      TEXT,                             -- Shopify displayFulfillmentStatus, as last seen
  fulfilled_at     TEXT,                             -- when the poll first saw it fulfilled in Shopify
  cancelled_at     TEXT,
  shop_changed_at  TEXT,                             -- lines changed in Shopify after it left 'queued' (slice 2+)
  first_seen_at    TEXT NOT NULL DEFAULT (datetime('now')),
  last_seen_at     TEXT NOT NULL DEFAULT (datetime('now'))   -- last poll that returned it open
);
CREATE INDEX IF NOT EXISTS idx_shop_orders_state ON shop_orders (state, rush, placed_at);

CREATE TABLE IF NOT EXISTS shop_order_lines (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id         INTEGER NOT NULL REFERENCES shop_orders (id),
  shop_line_gid    TEXT NOT NULL UNIQUE,             -- gid://shopify/LineItem/456
  title            TEXT,                             -- product title (no buyer data in it)
  variant_title    TEXT,
  cultivar         TEXT,                             -- "Sour Lifter" (Payton's = Peyton's)
  floor_cultivar   TEXT,                             -- "2026 - Sour Lifter / Sungrown" for cell lines: the floor's spelling
  form             TEXT,                             -- 'tops' | 'smalls' | 'trim' | NULL
  bag              TEXT,                             -- qOz hOz oz1 qLb hLb lb1 lb10 kg1 kg5 pallet | NULL
  qty              INTEGER NOT NULL DEFAULT 0,
  qty_open         INTEGER NOT NULL DEFAULT 0,       -- unfulfilled quantity, as last seen
  route            TEXT NOT NULL CHECK (route IN ('cell', 'bagging', 'pack', 'wholesale', 'ask')),
  route_why        TEXT,
  sort             INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_shop_order_lines_order ON shop_order_lines (order_id);

-- One row: how the last poll went, for the page's "Synced 2 min ago" and errors.
CREATE TABLE IF NOT EXISTS shop_sync (
  id               INTEGER PRIMARY KEY CHECK (id = 1),
  last_try_at      TEXT,
  last_ok_at       TEXT,
  last_error       TEXT,
  last_count       INTEGER
);

-- ===== migrations/0060-pickup-spot.sql =====
-- 0060: baskets waiting at the pickup spot (Koa 2026-11-11, "Yes, both").
-- Two weight-matched baskets per cell: at the chime the trimmer moves the full
-- basket to a marked pickup spot beside the cell and sets the matched empty one
-- on the scale, which closes the job (a pickup mark). The Cells board shows every
-- pickup not yet collected as "waiting at pickup spot" until bag/tag taps it
-- collected (?action=collectPickup).
-- Everything picked up before this migration counts as collected.
-- Apply by hand: cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0060-pickup-spot.sql
ALTER TABLE scale_marks ADD COLUMN collected_at TEXT;
-- The order-flow job the pickup closed (cell_jobs, order flow slice 2); NULL when
-- the order was picked by hand on the screen.
ALTER TABLE scale_marks ADD COLUMN job_id INTEGER;
UPDATE scale_marks SET collected_at = ts WHERE kind = 'pickup';
CREATE INDEX IF NOT EXISTS idx_scale_marks_waiting ON scale_marks(kind, collected_at, ts);

-- ===== migrations/0061-order-assign.sql =====
-- Order flow, slice 2: automatic assignment of Shopify orders to cells, with
-- NOW / NEXT per cell (design doc §2e; Koa 2026-11-11: "automatic order
-- assignment, 1 click printing, order queue, and flow").
--
-- A cell job is one basket of one cultivar for one order (lib/order-assign.js
-- splits a line into baskets of at most one 1 lb fill). A cell's NOW is its
-- first queued job by seq, NEXT the second. A cell holds at most two orders.
--
-- Run ONCE: the ALTER TABLE lines are not idempotent in SQLite. Needs 0058 and
-- 0060 (0060-pickup-spot adds scale_marks.job_id and collected_at: the pickup
-- mark is the one store for "waiting at the pickup spot").
-- Apply by hand:
--   cd workers && npx wrangler d1 execute rogue-origin-db --remote --file=migrations/0061-order-assign.sql

CREATE TABLE IF NOT EXISTS cell_jobs (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id      INTEGER NOT NULL REFERENCES shop_orders (id),
  line_id       INTEGER REFERENCES shop_order_lines (id),
  station_id    TEXT NOT NULL,
  seq           INTEGER NOT NULL,                 -- work order at the cell (rising)
  cultivar      TEXT NOT NULL,                    -- the floor's spelling: "2026 - Sour Lifter / Sungrown"
  bag           TEXT NOT NULL,                    -- qOz hOz oz1 qLb hLb lb1 (the cell screen's keys)
  bags          INTEGER NOT NULL,                 -- bags this basket fills
  target_g      REAL NOT NULL,                    -- bags x fill standard
  basket_no     INTEGER NOT NULL DEFAULT 1,       -- "basket 1 of 2" within its line
  baskets       INTEGER NOT NULL DEFAULT 1,
  state         TEXT NOT NULL DEFAULT 'queued' CHECK (state IN ('queued', 'done', 'cancelled')),
  assigned_by   TEXT NOT NULL DEFAULT 'auto',     -- auto | moved (bag/tag moved it)
  why           TEXT,                             -- why this cell (same cultivar, frees up soonest...)
  assigned_at   TEXT NOT NULL DEFAULT (datetime('now')),
  started_at    TEXT,                             -- the cell screen started trimming it
  done_at       TEXT,                             -- basket lifted to the pickup spot (or tapped done)
  done_by       TEXT,                             -- scale | tap
  net_g         REAL,                             -- what the basket held at the pickup
  cycle_s       INTEGER,
  collected_at  TEXT                              -- bag/tag took it from the pickup spot
);
CREATE INDEX IF NOT EXISTS idx_cell_jobs_station ON cell_jobs (station_id, state, seq);
CREATE INDEX IF NOT EXISTS idx_cell_jobs_order ON cell_jobs (order_id);

-- Which cells take orders (Koa 2026-11-10/11: table1 and the retail cells 12-14 now).
ALTER TABLE cell_roster ADD COLUMN takes_orders INTEGER NOT NULL DEFAULT 0;
UPDATE cell_roster SET takes_orders = 1 WHERE station_id IN ('table1', 'table12', 'table13', 'table14');

-- Bag/tag's one click (confirm; slice 4 adds the printing to it), and the pickup spot.
ALTER TABLE shop_orders ADD COLUMN confirmed_at TEXT;
ALTER TABLE shop_orders ADD COLUMN assigned_at TEXT;
ALTER TABLE shop_orders ADD COLUMN ready_at TEXT;       -- every basket at its cell's pickup spot
ALTER TABLE shop_orders ADD COLUMN collected_at TEXT;   -- bag/tag took them: on to check-weigh
ALTER TABLE shop_order_lines ADD COLUMN route_set_by TEXT;   -- NULL = the route module; 'bagtag' = picked by hand

-- The demo driver's own state (handlers/production/demo.js).
CREATE TABLE IF NOT EXISTS demo_state (key TEXT PRIMARY KEY, value TEXT NOT NULL);
-- The marker the Worker checks before any demo request (lib/demo-env.js verifyDemoDb):
-- a binding pointed at the live database by mistake has no such row, and is refused.
INSERT OR IGNORE INTO demo_state (key, value) VALUES ('database', 'rogue-origin-demo');
CREATE TABLE IF NOT EXISTS demo_arrivals (
  id      INTEGER PRIMARY KEY AUTOINCREMENT,
  sim_at  INTEGER NOT NULL,      -- sim clock ms when the order arrives
  payload TEXT NOT NULL,         -- the mock order: name, rush, lines (no buyer fields)
  done    INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_demo_arrivals_due ON demo_arrivals (done, sim_at);
-- When (sim clock ms) the demo first saw each order assigned / ready / collected:
-- auto bag/tag times its steps on the sim clock, never on the database's wall clock.
CREATE TABLE IF NOT EXISTS demo_orders (
  order_id     INTEGER PRIMARY KEY,
  seen_at      INTEGER,
  ready_at     INTEGER,
  collected_at INTEGER
);
CREATE TABLE IF NOT EXISTS demo_jobs (
  job_id       INTEGER PRIMARY KEY,  -- cell_jobs.id being trimmed
  grams        REAL NOT NULL DEFAULT 0,
  phase        TEXT NOT NULL DEFAULT 'trim',   -- trim | swapped
  swapped_real INTEGER
);
